const sk1 = sketch('top')
sk1.rect(40, 30, { at: [20, 15] })
const plate = extrude(sk1, 10)
const sk2 = sketch('top', 10)
sk2.rect(10, 10, { at: [20, 15] })
const part = pocket(sk2, plate, 4)
round(part.rim(sk2), 1)
round(part.edge('top','front'), 1)

const sk1 = sketch('top')
sk1.rect(40, 30, { at: [20, 15] })
const plate = extrude(sk1, 10)
const sk2 = sketch('top', 10)
sk2.rect(10, 10, { at: [20, 15] })
const part = pocket(sk2, plate, 4)
round(part.rim(sk2), 1)
round(part.edge('top','front'), 2)

const sk1 = sketch('top')
sk1.rect(40, 30, { at: [20, 15] })
const plate = extrude(sk1, 10)
const sk2 = sketch('top', 10)
sk2.rect(10, 10, { at: [20, 15] })
const part = pocket(sk2, plate, 4)
round(part.rim(sk2), 1)
round(part.edge('top', part.wall(sk2, 1)), 2)

const sk1 = sketch('top')
sk1.rect(40, 30, { at: [20, 15] })
const plate = extrude(sk1, 10)
round([plate.edge('top','front')], 2)
